    // 메모리 사용량 < 4KB (L1 캐시)
    let memory = net.memory_usage();

    if memory > 4096 {
        return false;
    }

    // 정확한 크기 확인: 1024 + 64 + 512 + 32 = 1632 bytes
    if memory != 1632 {
        return false;
    }

