   Group B (B1-B10): Hardware Optimizer - DVFS + Thermal
   Group C (C1-C10): Threat Engine - Real-time Prediction
   Group D (D1-D10): Distributed Optimizer - Consensus + Self-Optimization

   목표: 40/40 테스트 통과 (100%)
   8개 무관용 규칙 달성 (100%)
============================================================================ */

use crate::l0_engine::{
    SimdVec4, SimdMatrix, simd_dot_product, simd_relu,
    validate_simd_vec4, validate_simd_matrix, validate_simd_accuracy,
    L0NeuralNet, L0BatchProcessor,
    validate_l0_inference_speed, validate_l0_memory, validate_l0_output, validate_l0_accuracy,
};

use crate::hardware_optimizer::{
    DVFSState, WorkloadProfile, DVFSPredictor, DVFSController,
