// ============================================================================
// Group A: L0 Engine Tests (A1-A10)
// ============================================================================

/// Test A1: SIMD 벡터 연산 정확도
pub fn test_a1_simd_vec4_operations() -> bool {
    let v1 = SimdVec4::new(1.0, 2.0, 3.0, 4.0);
    let v2 = SimdVec4::new(5.0, 6.0, 7.0, 8.0);

    // 덧셈
    let add_result = v1.add(&v2);
    if (add_result.v[0] - 6.0).abs() > 1e-6 || (add_result.v[3] - 12.0).abs() > 1e-6 {
        return false;
    }

    // 곱셈
    let mul_result = v1.mul(&v2);
    if (mul_result.v[0] - 5.0).abs() > 1e-6 || (mul_result.v[3] - 32.0).abs() > 1e-6 {
        return false;
    }

    // 내적: 1*5 + 2*6 + 3*7 + 4*8 = 5+12+21+32 = 70
    let dot = v1.horizontal_sum() * v2.horizontal_sum();
    if (v1.v[0] * v2.v[0] + v1.v[1] * v2.v[1] + v1.v[2] * v2.v[2] + v1.v[3] * v2.v[3] - 70.0).abs() > 1e-6 {
        return false;
    }

    if !validate_simd_vec4(&v1) {
        return false;
    }

    true
}

