/// Test A3: SIMD 행렬 - 벡터 곱
pub fn test_a3_simd_matrix_vector_multiply() -> bool {
    let mut mat = SimdMatrix::new();

    // 단순 행렬: [1 2 ... 16; 17 18 ... 32; ...]
    for i in 0..16 {
        for j in 0..16 {
            mat.rows[i][j] = (i * 16 + j + 1) as f32;
        }
    }

    let mut vec = [1.0f32; 16];

    let result = mat.mul_vec(&vec);

    // 첫 번째 행: 1+2+...+16 = 136
    let first_row_sum = (1..=16).sum::<u32>() as f32;
    if (result[0] - first_row_sum).abs() > 1e-4 {
        return false;
    }

    true
}

