pub fn test_a4_simd_matrix_transpose() -> bool {
    let mut mat = SimdMatrix::new();
    for i in 0..16 {
        for j in 0..16 {
            mat.rows[i][j] = (i * 10 + j) as f32;
        }
    }

    let transposed = mat.transpose();

    // mat[i][j] == transposed[j][i]
    for i in 0..16 {
        for j in 0..16 {
            if (mat.rows[i][j] - transposed.rows[j][i]).abs() > 1e-6 {
                return false;
            }
        }
    }

    true
}

