        for (i, &b) in bytes.iter().enumerate() {
            if i >= 32 {
                break;
            }
            test_name[i] = b;
        }

        TestResult {
            test_name,
            passed: false,
            assertions: 0,
            failures: 0,
            duration_us: 0,
        }
    }

    pub fn assert_true(&mut self, condition: bool, msg: &str) {
        self.assertions += 1;
        if !condition {
            self.failures += 1;
        }
    }

