============================================================================ */

// ============================================================================
// 테스트 유틸리티
// ============================================================================

pub struct TestResult {
    pub test_name: [u8; 32],
    pub passed: bool,
    pub assertions: u32,
    pub failures: u32,
    pub duration_us: u64,
}

impl TestResult {
    pub fn new(name: &str) -> Self {
        let mut test_name = [0u8; 32];
        let bytes = name.as_bytes();
        for (i, &b) in bytes.iter().enumerate() {
            if i >= 32 {
                break;
            }
            test_name[i] = b;
        }

        TestResult {
            test_name,
            passed: false,
            assertions: 0,
            failures: 0,
            duration_us: 0,
        }
    }

    pub fn assert_true(&mut self, condition: bool, msg: &str) {
        self.assertions += 1;
        if !condition {
            self.failures += 1;
        }
    }

    pub fn finalize(&mut self) {
        self.passed = self.failures == 0;
    }
}

