   295→// 4. 검증 함수
   296→// ============================================================================
   297→
   298→pub fn validate_threat_type(threat: ThreatType) -> bool {
   299→    threat.is_valid()
   300→}
   301→
   302→pub fn validate_threat_score(score: f32) -> bool {
