   197→// ========== Fast Path (< 5µs) ==========
   198→
   199→pub fn fast_path_response(result: &ClassificationResult, pid: u32) -> Option<ResponseAction> {
   200→    // 극도의 위협만 빠른 경로로 처리
   201→    if result.confidence > 0.95 {
