    12→   4. reboot - 재부팅
    13→   5. echo - 문자열 출력
    14→   6. gpio - GPIO 제어
    15→   7. dvfs - DVFS 상태
    16→============================================================================ */
    17→
    18→// ============================================================================
    19→// 1. 명령어 정의
    20→// ============================================================================
    21→
    22→#[derive(Clone, Copy, PartialEq)]
    23→pub enum ShellCommand {
    24→    Help = 0,
    25→    Mem = 1,
    26→    Tasks = 2,
    27→    Reboot = 3,
    28→    Echo = 4,
    29→    Gpio = 5,
    30→    Dvfs = 6,
    31→    Unknown = 255,
    32→}
    33→
    34→impl ShellCommand {
    35→    pub fn from_str(s: &str) -> Self {
    36→        match s {
    37→            "help" => ShellCommand::Help,
    38→            "mem" => ShellCommand::Mem,
    39→            "tasks" => ShellCommand::Tasks,
    40→            "reboot" => ShellCommand::Reboot,
    41→            "echo" => ShellCommand::Echo,
    42→            "gpio" => ShellCommand::Gpio,
    43→            "dvfs" => ShellCommand::Dvfs,
    44→            _ => ShellCommand::Unknown,
    45→        }
    46→    }
    47→
    48→    pub fn to_str(&self) -> &str {
    49→        match self {
    50→            ShellCommand::Help => "help",
    51→            ShellCommand::Mem => "mem",
    52→            ShellCommand::Tasks => "tasks",
    53→            ShellCommand::Reboot => "reboot",
    54→            ShellCommand::Echo => "echo",
    55→            ShellCommand::Gpio => "gpio",
    56→            ShellCommand::Dvfs => "dvfs",
    57→            ShellCommand::Unknown => "unknown",
    58→        }
    59→    }
    60→}
    61→
    62→// ============================================================================
    63→// 2. 명령어 인자 구조체
    64→// ============================================================================
    65→
    66→pub struct ShellCommandArgs {
    67→    pub command: ShellCommand,
    68→    pub args: [u8; 128],          // 인자 버퍼
    69→    pub arg_count: u8,             // 인자 개수
    70→}
    71→
    72→impl ShellCommandArgs {
    73→    pub fn new(cmd: ShellCommand) -> Self {
    74→        ShellCommandArgs {
    75→            command: cmd,
    76→            args: [0u8; 128],
    77→            arg_count: 0,
    78→        }
    79→    }
    80→
    81→    pub fn with_args(mut self, args: &str) -> Self {
    82→        let bytes = args.as_bytes();
    83→        for (i, &b) in bytes.iter().enumerate() {
    84→            if i >= 128 {
    85→                break;
    86→            }
    87→            self.args[i] = b;
    88→        }
    89→        self.arg_count = bytes.len().min(128) as u8;
    90→        self
    91→    }
    92→}
