    95→// 3. 셸 결과 타입
    96→// ============================================================================
    97→
    98→pub enum ShellResult {
    99→    Success(u32),           // 성공 + 반환값
   100→    Error(u32),             // 오류 코드
   101→    Exit,                   // 셸 종료
   102→    Unknown,                // 알 수 없는 명령
   103→}
