   105→// ============================================================================
   106→// 4. 셸 상태
   107→// ============================================================================
   108→
   109→pub struct ShellState {
   110→    pub running: bool,
   111→    pub command_count: u32,
   112→    pub error_count: u32,
   113→    pub success_count: u32,
   114→    pub prompt: [u8; 32],
   115→}
   116→
   117→impl ShellState {
   118→    pub fn new() -> Self {
   119→        let mut prompt = [0u8; 32];
   120→        let p = b"freeos> ";
   121→        for (i, &b) in p.iter().enumerate() {
   122→            if i >= 32 {
   123→                break;
   124→            }
   125→            prompt[i] = b;
   126→        }
   127→
   128→        ShellState {
   129→            running: true,
   130→            command_count: 0,
   131→            error_count: 0,
