   142→// ============================================================================
   143→// 5. 나노 셸
   144→// ============================================================================
   145→
   146→pub struct NanoShell {
   147→    pub state: ShellState,
   148→    pub buffer: [u8; 256],         // 입력 버퍼
   149→    pub buffer_pos: u32,
   150→}
   151→
   152→impl NanoShell {
   153→    pub fn new() -> Self {
   154→        NanoShell {
   155→            state: ShellState::new(),
   156→            buffer: [0u8; 256],
   157→            buffer_pos: 0,
   158→        }
   159→    }
   160→
   161→    /// 명령어 파싱
   162→    pub fn parse_command(&mut self, input: &str) -> Option<ShellCommandArgs> {
   163→        // 입력 비우기
   164→        self.buffer_pos = 0;
   165→
   166→        // 명령어와 인자 분리
   167→        let mut parts = input.split_whitespace();
   168→
   169→        let cmd_str = parts.next()?;
   170→        let command = ShellCommand::from_str(cmd_str);
   171→
   172→        // 인자 수집
   173→        let remaining = parts
   174→            .map(|s| s.to_string())
   175→            .collect::<Vec<String>>()
   176→            .join(" ");
   177→
   178→        Some(ShellCommandArgs::new(command).with_args(&remaining))
   179→    }
   180→
   181→    /// 명령어 실행
   182→    pub fn execute_command(&mut self, args: ShellCommandArgs) -> ShellResult {
   183→        self.state.command_count += 1;
   184→
   185→        match args.command {
   186→            ShellCommand::Help => self.cmd_help(),
   187→            ShellCommand::Mem => self.cmd_mem(),
   188→            ShellCommand::Tasks => self.cmd_tasks(),
   189→            ShellCommand::Reboot => self.cmd_reboot(),
   190→            ShellCommand::Echo => self.cmd_echo(&args),
   191→            ShellCommand::Gpio => self.cmd_gpio(&args),
   192→            ShellCommand::Dvfs => self.cmd_dvfs(&args),
   193→            ShellCommand::Unknown => {
   194→                self.state.error_count += 1;
   195→                ShellResult::Error(1)
   196→            },
   197→        }
   198→    }
   199→
   200→    /// help 명령
   201→    fn cmd_help(&mut self) -> ShellResult {
   202→        self.state.success_count += 1;
   203→
   204→        // 도움말 출력 (시뮬레이션)
   205→        // println!("Available commands:");
   206→        // println!("  help   - Show this help");
   207→        // println!("  mem    - Display memory status");
   208→        // println!("  tasks  - List tasks");
   209→        // println!("  reboot - Reboot system");
   210→        // println!("  echo   - Echo text");
   211→        // println!("  gpio   - GPIO control");
   212→        // println!("  dvfs   - DVFS status");
   213→
   214→        ShellResult::Success(0)
   215→    }
   216→
   217→    /// mem 명령 (메모리 상태)
   218→    fn cmd_mem(&mut self) -> ShellResult {
   219→        self.state.success_count += 1;
   220→
   221→        // 메모리 정보 반환 (시뮬레이션)
   222→        // Total: 1MB, Used: 256KB, Free: 768KB
   223→
   224→        ShellResult::Success(256)  // 256KB 사용
   225→    }
   226→
   227→    /// tasks 명령 (태스크 목록)
   228→    fn cmd_tasks(&mut self) -> ShellResult {
   229→        self.state.success_count += 1;
   230→
   231→        // 태스크 목록 출력 (시뮬레이션)
   232→        // TID | Name      | State   | Priority
   233→        // 1   | idle      | Running | 0
   234→        // 2   | shell     | Ready   | 10
   235→        // 3   | watchdog  | Ready   | 20
   236→
   237→        ShellResult::Success(3)  // 3개 태스크
   238→    }
   239→
   240→    /// reboot 명령
   241→    fn cmd_reboot(&mut self) -> ShellResult {
   242→        self.state.success_count += 1;
   243→        self.state.stop();
   244→
   245→        // 실제 재부팅: CPU 리셋
   246→
   247→        ShellResult::Exit
   248→    }
   249→
   250→    /// echo 명령
   251→    fn cmd_echo(&mut self, args: &ShellCommandArgs) -> ShellResult {
   252→        self.state.success_count += 1;
   253→
   254→        // 인자 출력 (시뮬레이션)
   255→        // println!("{}", String::from_utf8_lossy(&args.args[..args.arg_count as usize]));
   256→
   257→        ShellResult::Success(args.arg_count as u32)
   258→    }
   259→
   260→    /// gpio 명령
   261→    fn cmd_gpio(&mut self, args: &ShellCommandArgs) -> ShellResult {
   262→        self.state.success_count += 1;
   263→
   264→        // GPIO 제어 예: "gpio 4 1" (핀 4를 HIGH로)
   265→        // 첫 인자: 핀 번호, 두 번째 인자: 값 (0=LOW, 1=HIGH)
   266→
   267→        ShellResult::Success(0)
   268→    }
   269→
   270→    /// dvfs 명령
   271→    fn cmd_dvfs(&mut self, args: &ShellCommandArgs) -> ShellResult {
   272→        self.state.success_count += 1;
   273→
   274→        // DVFS 상태 표시
   275→        // Current frequency: 1.5 GHz
   276→        // Available: 400MHz, 800MHz, 1.2GHz, 1.5GHz, 2.0GHz
   277→
   278→        ShellResult::Success(1500)  // 1500 MHz
   279→    }
   280→
   281→    /// 셸 루프 (싱글 명령)
   282→    pub fn execute_one(&mut self, input: &str) -> ShellResult {
   283→        if let Some(args) = self.parse_command(input) {
   284→            self.execute_command(args)
   285→        } else {
   286→            self.state.error_count += 1;
   287→            ShellResult::Error(1)
   288→        }
   289→    }
   290→
   291→    /// 통계
   292→    pub fn stats(&self) -> (u32, u32, u32) {
   293→        (
   294→            self.state.command_count,
   295→            self.state.success_count,
   296→            self.state.error_count,
   297→        )
   298→    }
   299→}
