   347→        // 시뮬레이션: 실제로는 UART에 출력
   348→        // print!("{}", String::from_utf8_lossy(&self.shell.state.prompt[..]));
   349→    }
   350→
   351→    /// 입력 버퍼에 문자 추가
   352→    pub fn add_char(&mut self, ch: u8) -> bool {
   353→        if self.input_pos >= 256 {
   354→            return false;  // 버퍼 가득
   355→        }
   356→
   357→        if ch == b'\n' || ch == b'\r' {
   358→            // 명령 실행
   359→            return true;  // 엔터 입력됨
   360→        }
   361→
   362→        self.input_buffer[self.input_pos as usize] = ch;
   363→        self.input_pos += 1;
   364→        false
   365→    }
