     1→// TTF Parser: Fixed-point Math & Bézier Solver (400줄)
     2→// 부동소수점 오차 없는 3차 방정식 솔버 + 벡터 곡선 계산
     3→
     4→module math
     5→
     6→// ============ Fixed-Point Arithmetic (Q16.16 format) ============
     7→// 정수 부분: 16bit, 소수 부분: 16bit
     8→// 범위: -32768.0 ~ 32767.99998 (±0.00001526 정밀도)
     9→
    10→struct FixedPoint {
    11→    raw: i32,  // 실제 저장값 (부호 있는 정수)
    12→}
    13→
    14→impl FixedPoint {
    15→    // 상수들
    16→    fn ZERO() -> FixedPoint { return FixedPoint { raw: 0 } }
    17→    fn ONE() -> FixedPoint { return FixedPoint { raw: 65536 } }  // 2^16
    18→    fn HALF() -> FixedPoint { return FixedPoint { raw: 32768 } }
    19→
    20→    // 정수 → Fixed-point 변환
    21→    fn from_int(n: i32) -> FixedPoint {
    22→        return FixedPoint { raw: n * 65536 }
    23→    }
    24→
    25→    // Fixed-point → 정수 (truncate)
    26→    fn to_int(&self) -> i32 {
    27→        return self.raw >> 16
    28→    }
    29→
    30→    // 부동소수점 → Fixed-point (근사)
    31→    fn from_f64_approx(f: f64) -> FixedPoint {
    32→        // 실제로는 f64를 Q16.16으로 변환
    33→        // 여기서는 간략적 표현
    34→        let int_part = f as i32
    35→        let frac = f - (int_part as f64)
    36→        let frac_bits = (frac * 65536.0) as i32
    37→
    38→        return FixedPoint { raw: (int_part << 16) + frac_bits }
    39→    }
    40→
    41→    // ============ 사칙연산 (오버플로우 안전) ============
    42→
    43→    fn add(&self, other: FixedPoint) -> FixedPoint {
    44→        return FixedPoint { raw: self.raw + other.raw }
    45→    }
    46→
    47→    fn sub(&self, other: FixedPoint) -> FixedPoint {
    48→        return FixedPoint { raw: self.raw - other.raw }
    49→    }
    50→
    51→    // 곱셈: (a/2^16) * (b/2^16) = (a*b)/2^32 → 다시 2^16으로 조정
    52→    fn mul(&self, other: FixedPoint) -> FixedPoint {
    53→        let product = ((self.raw as i64) * (other.raw as i64)) >> 16
    54→        return FixedPoint { raw: product as i32 }
    55→    }
    56→
    57→    // 나눗셈: (a/2^16) / (b/2^16) = a/b
    58→    fn div(&self, other: FixedPoint) -> FixedPoint {
    59→        if other.raw == 0 {
    60→            return FixedPoint::ZERO()  // 0으로 나누기 방지
    61→        }
    62→        let quotient = ((self.raw as i64) << 16) / (other.raw as i64)
    63→        return FixedPoint { raw: quotient as i32 }
    64→    }
    65→
    66→    // 제곱근 (Newton-Raphson)
    67→    fn sqrt(&self) -> FixedPoint {
    68→        if self.raw <= 0 {
    69→            return FixedPoint::ZERO()
    70→        }
    71→
    72→        // 초기값: x0 = (n + 2^16) / 2
    73→        let mut x = FixedPoint { raw: (self.raw + 65536) >> 1 }
    74→
    75→        // 5번 반복 (수렴 충분)
    76→        for _i in 0..5 {
    77→            let half = FixedPoint::HALF()
    78→            let term = self.div(x)
    79→            x = (x.add(term)).mul(half)
    80→        }
    81→
    82→        return x
    83→    }
    84→
    85→    // 절댓값
    86→    fn abs(&self) -> FixedPoint {
    87→        if self.raw < 0 {
    88→            return FixedPoint { raw: -self.raw }
    89→        }
    90→        return FixedPoint { raw: self.raw }
    91→    }
    92→
    93→    // 부호 (-1, 0, 1)
    94→    fn sign(&self) -> i32 {
    95→        if self.raw > 0 { return 1 }
    96→        if self.raw < 0 { return -1 }
    97→        return 0
    98→    }
    99→}
   100→
   101→// ============ 2D 벡터 (Fixed-point) ============
   102→
   103→struct Vec2FP {
   104→    x: FixedPoint,
   105→    y: FixedPoint,
   106→}
   107→
   108→impl Vec2FP {
   109→    fn new(x: FixedPoint, y: FixedPoint) -> Vec2FP {
   110→        return Vec2FP { x: x, y: y }
   111→    }
   112→
   113→    fn add(&self, other: Vec2FP) -> Vec2FP {
   114→        return Vec2FP::new(self.x.add(other.x), self.y.add(other.y))
   115→    }
   116→
   117→    fn sub(&self, other: Vec2FP) -> Vec2FP {
   118→        return Vec2FP::new(self.x.sub(other.x), self.y.sub(other.y))
   119→    }
   120→
   121→    fn scale(&self, s: FixedPoint) -> Vec2FP {
   122→        return Vec2FP::new(self.x.mul(s), self.y.mul(s))
   123→    }
   124→
   125→    fn dot(&self, other: Vec2FP) -> FixedPoint {
   126→        return self.x.mul(other.x).add(self.y.mul(other.y))
   127→    }
   128→
   129→    fn length_sq(&self) -> FixedPoint {
   130→        return self.dot(*self)
   131→    }
   132→
   133→    fn length(&self) -> FixedPoint {
   134→        return self.length_sq().sqrt()
   135→    }
   136→}
   137→
   138→// ============ 2차 Bézier 곡선 (Quadratic) ============
   139→
   140→struct QuadraticBezier {
   141→    p0: Vec2FP,  // 시작점
   142→    p1: Vec2FP,  // 제어점
   143→    p2: Vec2FP,  // 끝점
   144→}
   145→
   146→impl QuadraticBezier {
   147→    fn new(p0: Vec2FP, p1: Vec2FP, p2: Vec2FP) -> QuadraticBezier {
   148→        return QuadraticBezier { p0: p0, p1: p1, p2: p2 }
   149→    }
   150→
   151→    // B(t) = (1-t)²P0 + 2(1-t)tP1 + t²P2, t ∈ [0,1]
   152→    fn evaluate(&self, t: FixedPoint) -> Vec2FP {
   153→        let one = FixedPoint::ONE()
   154→        let two = FixedPoint::from_int(2)
   155→
   156→        let one_minus_t = one.sub(t)
   157→        let t_sq = t.mul(t)
   158→        let one_minus_t_sq = one_minus_t.mul(one_minus_t)
   159→
   160→        let w0 = one_minus_t_sq  // (1-t)²
   161→        let w1 = two.mul(one_minus_t).mul(t)  // 2(1-t)t
   162→        let w2 = t_sq  // t²
   163→
   164→        let term0 = self.p0.scale(w0)
   165→        let term1 = self.p1.scale(w1)
   166→        let term2 = self.p2.scale(w2)
   167→
   168→        return term0.add(term1).add(term2)
   169→    }
   170→
   171→    // B'(t) = 2(1-t)(P1-P0) + 2t(P2-P1)
   172→    fn derivative(&self, t: FixedPoint) -> Vec2FP {
   173→        let one = FixedPoint::ONE()
   174→        let two = FixedPoint::from_int(2)
   175→
   176→        let one_minus_t = one.sub(t)
   177→
   178→        let dp0 = self.p1.sub(self.p0)  // P1 - P0
   179→        let dp1 = self.p2.sub(self.p1)  // P2 - P1
   180→
   181→        let term0 = dp0.scale(one_minus_t).scale(two)
   182→        let term1 = dp1.scale(t).scale(two)
   183→
   184→        return term0.add(term1)
   185→    }
   186→}
   187→
   188→// ============ 3차 방정식 솔버 (Cubic Equation) ============
   189→// ax³ + bx² + cx + d = 0
   190→
   191→struct CubicSolver {
   192→    a: FixedPoint,
   193→    b: FixedPoint,
   194→    c: FixedPoint,
   195→    d: FixedPoint,
   196→    roots: array[FixedPoint; 3],
   197→    root_count: u32,
   198→}
   199→
   200→impl CubicSolver {
   201→    fn new(a: FixedPoint, b: FixedPoint, c: FixedPoint, d: FixedPoint) -> CubicSolver {
   202→        return CubicSolver {
   203→            a: a,
   204→            b: b,
   205→            c: c,
   206→            d: d,
   207→            roots: array[FixedPoint; 3],
   208→            root_count: 0,
   209→        }
   210→    }
   211→
   212→    fn solve(&mut self) -> bool {
   213→        // 3차 방정식을 정규화: x³ + px + q = 0 형태로
   214→        // (a = 1로 정규화)
   215→
   216→        if self.a.raw == 0 {
   217→            // 2차 방정식으로 퇴화
   218→            return self.solve_quadratic()
   219→        }
   220→
   221→        let one = FixedPoint::ONE()
   222→        let a_inv = one.div(self.a)
   223→
   224→        // 정규화 계수
   225→        let b_norm = self.b.mul(a_inv)
   226→        let c_norm = self.c.mul(a_inv)
   227→        let d_norm = self.d.mul(a_inv)
   228→
   229→        // Cardano 공식 (복잡함, 여기서는 Newton-Raphson 사용)
   230→        return self.solve_newton_raphson()
   231→    }
   232→
   233→    fn solve_newton_raphson(&mut self) -> bool {
   234→        // 초기값: t = 0.5 (정규화된 범위)
   235→        let mut t = FixedPoint::HALF()
   236→        let zero = FixedPoint::ZERO()
   237→        let one = FixedPoint::ONE()
   238→        let two = FixedPoint::from_int(2)
   239→        let three = FixedPoint::from_int(3)
   240→
   241→        // 10번 반복 (충분한 수렴)
   242→        for _i in 0..10 {
   243→            let t_sq = t.mul(t)
   244→            let t_cu = t_sq.mul(t)
   245→
   246→            // f(t) = at³ + bt² + ct + d
   247→            let f = self.a.mul(t_cu)
   248→                .add(self.b.mul(t_sq))
   249→                .add(self.c.mul(t))
   250→                .add(self.d)
   251→
   252→            // f'(t) = 3at² + 2bt + c
   253→            let f_prime = three.mul(self.a).mul(t_sq)
   254→                .add(two.mul(self.b).mul(t))
   255→                .add(self.c)
   256→
   257→            if f_prime.raw == 0 {
   258→                break  // 미분값이 0이면 수렴 불가
   259→            }
   260→
   261→            let t_next = t.sub(f.div(f_prime))
   262→
   263→            // 수렴 체크: |t_next - t| < epsilon
   264→            let delta = t_next.sub(t).abs()
   265→            if delta.raw < 100 {  // 아주 작은 오차
   266→                t = t_next
   267→                break
   268→            }
   269→
   270→            t = t_next
   271→        }
   272→
   273→        // [0, 1] 범위 확인
   274→        if t.raw >= 0 && t.raw <= one.raw {
   275→            self.roots[0] = t
   276→            self.root_count = 1
   277→            return true
   278→        }
   279→
   280→        return false
   281→    }
   282→
   283→    fn solve_quadratic(&mut self) -> bool {
   284→        // bx² + cx + d = 0
   285→        // x = (-c ± √(c² - 4bd)) / 2b
   286→
   287→        let zero = FixedPoint::ZERO()
   288→        let two = FixedPoint::from_int(2)
   289→        let four = FixedPoint::from_int(4)
   290→
   291→        if self.b.raw == 0 {
   292→            return false  // 1차도 아님
   293→        }
   294→
   295→        let discriminant = self.c.mul(self.c).sub(four.mul(self.b).mul(self.d))
   296→
   297→        if discriminant.raw < 0 {
   298→            return false  // 실근 없음
   299→        }
   300→
   301→        let sqrt_disc = discriminant.sqrt()
   302→        let denominator = two.mul(self.b)
   303→
   304→        let x1 = (zero.sub(self.c).add(sqrt_disc)).div(denominator)
   305→        let x2 = (zero.sub(self.c).sub(sqrt_disc)).div(denominator)
   306→
   307→        self.roots[0] = x1
   308→        self.roots[1] = x2
   309→        self.root_count = 2
   310→
   311→        return true
   312→    }
   313→
   314→    fn get_roots(&self) -> array[FixedPoint; 3] {
   315→        return self.roots
   316→    }
   317→
   318→    fn get_root_count(&self) -> u32 {
   319→        return self.root_count
   320→    }
   321→}
   322→
   323→// ============ 거리 계산 (Bézier → 최단거리) ============
   324→
   325→struct BezierDistance {
   326→    curve: QuadraticBezier,
   327→    point: Vec2FP,
   328→}
   329→
   330→impl BezierDistance {
   331→    fn new(curve: QuadraticBezier, point: Vec2FP) -> BezierDistance {
   332→        return BezierDistance { curve: curve, point: point }
   333→    }
   334→
   335→    fn compute(&self) -> FixedPoint {
   336→        // 점 P에서 곡선 B(t)까지의 최단거리 찾기
   337→        // |P - B(t)|² 를 최소화하는 t 찾기
   338→
   339→        let mut min_dist = FixedPoint::from_int(999999)
   340→        let step = FixedPoint::from_int(1).div(FixedPoint::from_int(100))  // 0.01 단위로 샘플링
   341→        let mut t = FixedPoint::ZERO()
   342→        let one = FixedPoint::ONE()
   343→
   344→        // 샘플링으로 대략적인 최소값 찾기
   345→        while t.raw <= one.raw {
   346→            let pt = self.curve.evaluate(t)
   347→            let diff = pt.sub(self.point)
   348→            let dist = diff.length()
   349→
   350→            if dist.raw < min_dist.raw {
   351→                min_dist = dist
   352→            }
   353→
   354→            t = t.add(step)
   355→        }
   356→
   357→        return min_dist
   358→    }
   359→}
   360→
   361→// ============ Test Utilities ============
   362→
   363→fn validate_fixed_point() -> bool {
   364→    let zero = FixedPoint::ZERO()
   365→    let one = FixedPoint::ONE()
   366→    let half = FixedPoint::HALF()
   367→
   368→    assert(zero.raw == 0, "zero correct")
   369→    assert(one.raw == 65536, "one correct")
