// 5. 유틸리티 함수
// ============================================================================

fn constant_time_eq(a: &[u8; 16], b: &[u8; 16]) -> bool {
    let mut result = 0u8;
    for i in 0..16 {
        result |= a[i] ^ b[i];
    }
    result == 0
}

// ============================================================================
// 6. Clone 구현
// ============================================================================

impl Clone for AesGcmContext {
