// ============================================================================
// 1. Signal Threat 분류
// ============================================================================

pub enum SignalThreat {
    Clean = 0,           // 정상 신호
    Jamming = 1,         // 재밍 (노이즈 공격)
    Spoofing = 2,        // 스푸핑 (위조 신호)
