}

impl L0NeuralNet {
    pub fn new() -> Self {
        L0NeuralNet {
            w1: [[0.1f32; 16]; 16],
            b1: [0.0f32; 16],
            w2: [[0.1f32; 8]; 16],
            b2: [0.0f32; 8],
        }
    }

    pub fn forward(&self, input: &[f32; 16]) -> [f32; 8] {
        // 은닉층: h = relu(W1 * x + b1)
        let mut hidden = [0.0f32; 16];
        for i in 0..16 {
            let mut sum = self.b1[i];
            for j in 0..16 {
                sum += self.w1[i][j] * input[j];
