// ============================================================================
// D1-D6: Kernel I/O Tests (Day 5-6)
// ============================================================================

use crate::kernel_io::{LedgerIoLayer, CommitBus, TxEvent, CASCore};

/// D1: CAS 저장
pub fn test_d1_cas_storage() -> bool {
    let mut cas = CASCore::new();
    let test_data = [1u8; 256];

    cas.store_chunk(0, &test_data);

    cas.chunk_count == 1 && cas.has_chunk(0)
}

/// D2: CAS 복원
pub fn test_d2_cas_retrieval() -> bool {
    let mut cas = CASCore::new();
    let mut test_data = [0u8; 4096];

    for i in 0..256 {
        test_data[i] = i as u8;
    }

    cas.store_chunk(0, &test_data);

    if let Some(chunk) = cas.retrieve_chunk(0) {
        chunk[0] == 0 && chunk[255] == 255
    } else {
        false
    }
}

/// D3: 무결성 검증
pub fn test_d3_integrity_verification() -> bool {
    let mut io_layer = LedgerIoLayer::new();
    let node = DagNode::new(
        100,
        [1u8; 32],
        [2u8; 32],
        [3u8; 256],
        5000u64,
        10u64,
        1000000000u64,
    );

    if let Some(manifest) = io_layer.persist_block(&node, 0) {
        matches!(io_layer.verify_block(0), crate::kernel_io::IntegrityStatus::Valid)
    } else {
        false
    }
}

/// D4: Zero-Copy 버스
pub fn test_d4_zero_copy_bus() -> bool {
    let mut bus = CommitBus::new();

    let event = TxEvent::new(1, 1, 1000000000u64, [0u8; 32]);
    bus.submit_tx(event);

    bus.pending_count() == 1
}

/// D5: 배치 처리량 (> 10K tx/s)
pub fn test_d5_batch_throughput() -> bool {
    let mut bus = CommitBus::new();

    // 1000개 트랜잭션 투입
    for i in 0..1000 {
        let event = TxEvent::new(0, i, 1000000000u64 + (i as u64), [0u8; 32]);
        bus.submit_tx(event);
    }

    // 배치 커밋 (16 × 64 = 1024개)
    for _ in 0..16 {
        let batch = bus.commit_batch();
        if batch.len() == 0 {
            break;
        }
    }

    // 처리량 > 10,000 tx/s 확인
    let throughput = bus.throughput_tps();
    throughput > 10000.0 && bus.committed_tx_count > 900
}

/// D6: I/O 계층 통계
pub fn test_d6_io_layer_stats() -> bool {
    let mut io_layer = LedgerIoLayer::new();

    for i in 0..10 {
        let node = DagNode::new(
            i,
            [i as u8; 32],
            [(i + 1) as u8; 32],
            [0u8; 256],
            1000u64,
            i as u64,
            1000000000u64 + i,
        );

        let _ = io_layer.persist_block(&node, i as u32);
    }

    io_layer.total_manifests == 10
        && io_layer.cas.chunk_count == 10
}

