// ============================================================================
// E1-E6: Chain Verifier Tests (Day 7-8)
// ============================================================================

use crate::integrity::{DagChainVerifier, LedgerAuditLog, EpochSnapshot};

/// E1: DAG 경로 검증
pub fn test_e1_dag_path_verification() -> bool {
    let mut pool = DagNodePool::new();
    let genesis = pool.get_node(0).unwrap();

    let n1 = DagNode::new(
        1,
        genesis.self_hash,
        [0u8; 32],
        [1u8; 256],
        1000u64,
        1u64,
        1000000001u64,
    );

    pool.add_node(n1.clone());

    let mut verifier = DagChainVerifier::new(genesis.self_hash);

    verifier.verify_dag_path(&pool, &genesis.self_hash, &n1.self_hash)
}

/// E2: 변조 탐지
pub fn test_e2_tamper_detection() -> bool {
    let pool = DagNodePool::new();
    let mut verifier = DagChainVerifier::new([0u8; 32]);

    let (valid, _) = verifier.full_dag_scan(&pool);

    valid  // 제네시스만 있으면 유효
}

/// E3: 에포크 체크포인트
pub fn test_e3_epoch_checkpoint() -> bool {
    let genesis_hash = [1u8; 32];
    let mut verifier = DagChainVerifier::new(genesis_hash);

    verifier.add_checkpoint(1, [2u8; 32]);
    verifier.add_checkpoint(2, [3u8; 32]);

    verifier.checkpoint_count == 3  // genesis + 2 checkpoints
}

/// E4: 부분 검증
pub fn test_e4_partial_verification() -> bool {
    let pool = DagNodePool::new();
    let genesis_hash = if let Some(gen) = pool.get_node(0) {
        gen.self_hash
    } else {
        return false;
    };

    let mut verifier = DagChainVerifier::new(genesis_hash);

    let (valid, nodes) = verifier.verify_from_checkpoint(&pool, 0);

    valid && nodes == genesis_hash
}

/// E5: 무결성 복구
pub fn test_e5_integrity_recovery() -> bool {
    let pool = DagNodePool::new();
    let genesis_hash = if let Some(gen) = pool.get_node(0) {
        gen.self_hash
    } else {
        return false;
    };

    let mut verifier = DagChainVerifier::new(genesis_hash);

    let (valid, _) = verifier.full_dag_scan(&pool);

    valid && verifier.verified_nodes >= 1
}

/// E6: 검증기 통계
pub fn test_e6_verifier_stats() -> bool {
    let pool = DagNodePool::new();
    let mut verifier = DagChainVerifier::new([0u8; 32]);

    let (_, _) = verifier.full_dag_scan(&pool);

    verifier.verification_rate() > 90.0
}

