/// F4: 에포크 수렴
pub fn test_f4_epoch_convergence() -> bool {
    let mut dag = DagNodePool::new();
    let genesis = dag.get_node(0).unwrap();
    let mut audit_log = LedgerAuditLog::new();

    for i in 0..5 {
        audit_log.take_snapshot(i as u64, &dag, genesis.self_hash);
