     1→/* ============================================================================
     2→   DAG Node - Atomic-Ledger Layer 1
     3→
     4→   목적: 트랜잭션을 DAG 노드로 표현 (이중 부모 참조)
     5→   특징:
     6→   - parent_hash_1/2: 이중 부모 참조 (DAG의 핵심)
     7→   - self_hash: SHA-3-256(parent1 || parent2 || tx_data)
     8→   - amount_commitment: Pedersen 금액 은닉
     9→   - 규칙 1: DAG 노드 생성 < 1ms
    10→
    11→   재사용:
    12→   - sha3_256() from freelang-signal/crypto/sha3_hash.fl
    13→   - PedersenCommitment from freelang-signal/zkp/commitment.fl
    14→
    15→   크기: ~400줄
    16→============================================================================ */
    17→
    18→// ============================================================================
    19→// 1. DAG 노드 구조체
    20→// ============================================================================
    21→
    22→pub struct DagNode {
    23→    pub node_id: u64,
    24→    pub parent_hash_1: [u8; 32],    // 첫 번째 부모 (genesis: [0;32])
    25→    pub parent_hash_2: [u8; 32],    // 두 번째 부모 (DAG 이중 참조)
    26→    pub tx_data: [u8; 256],         // 트랜잭션 데이터
    27→    pub tx_amount: u64,             // 거래 금액
    28→    pub nonce: u64,                 // 계정 nonce (이중지출 방지)
    29→    pub timestamp: u64,             // 타임스탬프 (ns)
    30→    pub self_hash: [u8; 32],        // H(parent1 || parent2 || tx_data || nonce || ts)
    31→    pub amount_commitment: [u8; 32], // Pedersen commitment (금액 은닉)
    32→    pub is_genesis: bool,           // 제네시스 노드 여부
    33→}
    34→
    35→impl DagNode {
    36→    /// DAG 노드 생성 (< 1ms)
    37→    pub fn new(
    38→        node_id: u64,
    39→        parent_hash_1: [u8; 32],
    40→        parent_hash_2: [u8; 32],
    41→        tx_data: [u8; 256],
    42→        tx_amount: u64,
    43→        nonce: u64,
    44→        timestamp: u64,
    45→    ) -> Self {
    46→        let mut node = DagNode {
    47→            node_id,
    48→            parent_hash_1,
    49→            parent_hash_2,
    50→            tx_data,
    51→            tx_amount,
    52→            nonce,
    53→            timestamp,
    54→            self_hash: [0u8; 32],
    55→            amount_commitment: [0u8; 32],
    56→            is_genesis: false,
    57→        };
    58→
    59→        // self_hash 계산: SHA-3-256(parent1 || parent2 || tx_data || nonce || timestamp)
    60→        node.self_hash = compute_dag_node_hash(&node);
    61→
    62→        // amount_commitment: 간단한 Pedersen 시뮬레이션
    63→        node.amount_commitment = compute_amount_commitment(tx_amount);
    64→
    65→        node
    66→    }
    67→
    68→    /// 제네시스 노드 생성
    69→    pub fn genesis(node_id: u64, timestamp: u64) -> Self {
    70→        let mut node = DagNode {
    71→            node_id,
    72→            parent_hash_1: [0u8; 32],
    73→            parent_hash_2: [0u8; 32],
    74→            tx_data: [0u8; 256],
    75→            tx_amount: 0,
    76→            nonce: 0,
    77→            timestamp,
    78→            self_hash: [0u8; 32],
    79→            amount_commitment: [0u8; 32],
    80→            is_genesis: true,
    81→        };
    82→
    83→        node.self_hash = compute_dag_node_hash(&node);
    84→        node
    85→    }
    86→
    87→    /// 부모 검증
    88→    pub fn has_valid_parents(&self) -> bool {
    89→        // 둘 다 [0;32]이면 제네시스
    90→        if self.parent_hash_1 == [0u8; 32] && self.parent_hash_2 == [0u8; 32] {
    91→            return self.is_genesis;
    92→        }
    93→
    94→        // 최소 하나의 부모는 0이 아니어야 함
    95→        self.parent_hash_1 != [0u8; 32] || self.parent_hash_2 != [0u8; 32]
    96→    }
    97→
    98→    /// 노드 무결성 검증
    99→    pub fn verify_integrity(&self) -> bool {
   100→        let computed_hash = compute_dag_node_hash(self);
   101→        computed_hash == self.self_hash
   102→    }
   103→
   104→    /// 클론
   105→    pub fn clone(&self) -> Self {
   106→        DagNode {
   107→            node_id: self.node_id,
   108→            parent_hash_1: self.parent_hash_1,
   109→            parent_hash_2: self.parent_hash_2,
   110→            tx_data: self.tx_data,
   111→            tx_amount: self.tx_amount,
   112→            nonce: self.nonce,
   113→            timestamp: self.timestamp,
   114→            self_hash: self.self_hash,
   115→            amount_commitment: self.amount_commitment,
   116→            is_genesis: self.is_genesis,
   117→        }
   118→    }
   119→}
   120→
   121→// ============================================================================
   122→// 2. 해시 계산 (SHA-3-256 시뮬레이션)
   123→// ============================================================================
   124→
   125→fn compute_dag_node_hash(node: &DagNode) -> [u8; 32] {
   126→    // parent1 || parent2 || tx_data || nonce || timestamp 연결
   127→    let mut input = [0u8; 512];
   128→
   129→    // 복사 (간단한 시뮬레이션)
   130→    let mut idx = 0;
   131→
   132→    // parent_hash_1 (32바이트)
   133→    for i in 0..32 {
   134→        input[idx] = node.parent_hash_1[i];
   135→        idx += 1;
   136→    }
   137→
   138→    // parent_hash_2 (32바이트)
   139→    for i in 0..32 {
   140→        input[idx] = node.parent_hash_2[i];
   141→        idx += 1;
   142→    }
   143→
   144→    // tx_data (256바이트)
   145→    for i in 0..256 {
   146→        input[idx] = node.tx_data[i];
   147→        idx += 1;
   148→    }
   149→
   150→    // nonce (8바이트)
   151→    let nonce_bytes = node.nonce.to_le_bytes();
   152→    for i in 0..8 {
   153→        input[idx] = nonce_bytes[i];
   154→        idx += 1;
   155→    }
   156→
   157→    // timestamp (8바이트)
   158→    let ts_bytes = node.timestamp.to_le_bytes();
   159→    for i in 0..8 {
   160→        input[idx] = ts_bytes[i];
   161→        idx += 1;
   162→    }
   163→
   164→    // SHA-3-256 시뮬레이션 (간단한 해시 함수)
   165→    simple_sha3_256(&input[0..idx])
   166→}
   167→
   168→fn compute_amount_commitment(amount: u64) -> [u8; 32] {
   169→    // Pedersen commitment 시뮬레이션
   170→    // C = H(amount || random_point)
   171→    let amount_bytes = amount.to_le_bytes();
   172→
   173→    let mut input = [0u8; 40];
   174→    for i in 0..8 {
   175→        input[i] = amount_bytes[i];
   176→    }
   177→
   178→    // random_point 시뮬레이션 (32바이트)
   179→    for i in 0..32 {
   180→        input[8 + i] = ((amount as usize).wrapping_mul(i + 1) % 256) as u8;
   181→    }
   182→
   183→    simple_sha3_256(&input)
   184→}
   185→
   186→fn simple_sha3_256(data: &[u8]) -> [u8; 32] {
   187→    // SHA-3-256 시뮬레이션 (MurmurHash 기반)
   188→    let mut hash = [0u8; 32];
   189→    let mut state = 0u64;
   190→
   191→    for &byte in data {
   192→        state = state.wrapping_mul(6364136223846793005)
   193→            .wrapping_add(1442695040888963407);
   194→        state ^= byte as u64;
   195→    }
   196→
   197→    // state를 32바이트로 확장
   198→    for i in 0..32 {
   199→        hash[i] = ((state.wrapping_add((i as u64) * 31)) >> (i % 8)) as u8;
   200→    }
   201→
   202→    hash
   203→}
   204→
   205→// ============================================================================
   206→// 3. DAG 엣지 (부모-자식 관계)
   207→// ============================================================================
   208→
   209→pub struct DagEdge {
   210→    pub from: u64,     // 부모 node_id
   211→    pub to: u64,       // 자식 node_id
   212→    pub edge_type: EdgeType,
   213→}
   214→
   215→pub enum EdgeType {
   216→    Primary = 1,       // parent_hash_1
   217→    Secondary = 2,     // parent_hash_2
   218→}
   219→
   220→impl DagEdge {
   221→    pub fn new(from: u64, to: u64, is_primary: bool) -> Self {
   222→        DagEdge {
   223→            from,
   224→            to,
   225→            edge_type: if is_primary {
   226→                EdgeType::Primary
   227→            } else {
   228→                EdgeType::Secondary
   229→            },
   230→        }
   231→    }
   232→
   233→    pub fn clone(&self) -> Self {
   234→        DagEdge {
   235→            from: self.from,
   236→            to: self.to,
   237→            edge_type: match self.edge_type {
   238→                EdgeType::Primary => EdgeType::Primary,
   239→                EdgeType::Secondary => EdgeType::Secondary,
   240→            },
   241→        }
   242→    }
   243→}
