     1→/* ============================================================================
     2→   Commit Bus - Atomic-Ledger Layer 3
     3→
     4→   목적: Zero-Copy 트랜잭션 커밋 버스 (배치 처리)
     5→   특징:
     6→   - ZeroCopyRingBuffer 패턴 재사용 (Phase 8)
     7→   - 64개 트랜잭션 배치 원자 커밋
     8→   - 규칙 5: > 10,000 tx/s 처리량
     9→   - O(1) 투입/커밋
    10→
    11→   재사용:
    12→   - ZeroCopyRingBuffer from freelang-signal/src/transport/zero_copy_bus.fl
    13→
    14→   크기: ~350줄
    15→============================================================================ */
    16→
    17→// ============================================================================
    18→// 1. 트랜잭션 이벤트
    19→// ============================================================================
    20→
    21→pub struct TxEvent {
    22→    pub shard_id: u64,                // 샤드 ID (채널 ID와 유사)
    23→    pub tx_sequence: u64,             // 트랜잭션 시퀀스 번호
    24→    pub tx_payload: [u8; 512],        // 트랜잭션 페이로드
    25→    pub payload_len: u16,
    26→    pub timestamp_ns: u64,
    27→    pub dag_node_hash: [u8; 32],      // DAG 노드 해시
    28→}
    29→
    30→impl TxEvent {
    31→    pub fn new(shard_id: u64, tx_sequence: u64, timestamp_ns: u64, dag_node_hash: [u8; 32]) -> Self {
    32→        TxEvent {
    33→            shard_id,
    34→            tx_sequence,
    35→            tx_payload: [0u8; 512],
    36→            payload_len: 0,
    37→            timestamp_ns,
    38→            dag_node_hash,
    39→        }
    40→    }
    41→
    42→    pub fn clone(&self) -> Self {
    43→        TxEvent {
    44→            shard_id: self.shard_id,
    45→            tx_sequence: self.tx_sequence,
    46→            tx_payload: self.tx_payload,
    47→            payload_len: self.payload_len,
    48→            timestamp_ns: self.timestamp_ns,
    49→            dag_node_hash: self.dag_node_hash,
    50→        }
    51→    }
    52→}
    53→
    54→// ============================================================================
    55→// 2. Zero-Copy Ring Buffer (Phase 8 패턴)
    56→// ============================================================================
    57→
    58→pub struct ZeroCopyRingBuffer {
    59→    pub buffer: [Option<TxEvent>; 4096],
    60→    pub write_idx: u32,
    61→    pub read_idx: u32,
    62→    pub capacity: u32,
    63→    pub total_events: u64,
    64→}
    65→
    66→impl ZeroCopyRingBuffer {
    67→    pub fn new() -> Self {
    68→        ZeroCopyRingBuffer {
    69→            buffer: [None; 4096],
    70→            write_idx: 0,
    71→            read_idx: 0,
    72→            capacity: 4096,
    73→            total_events: 0,
    74→        }
    75→    }
    76→
    77→    /// O(1) 이벤트 투입
    78→    pub fn push(&mut self, event: TxEvent) -> bool {
    79→        let write_pos = self.write_idx as usize;
    80→
    81→        // 버퍼 가득 차면 oldest 항목 덮어쓰기
    82→        self.buffer[write_pos] = Some(event);
    83→        self.write_idx = (self.write_idx + 1) % self.capacity;
    84→        self.total_events += 1;
    85→
    86→        true
    87→    }
    88→
    89→    /// O(1) 이벤트 추출
    90→    pub fn pop(&mut self) -> Option<TxEvent> {
    91→        if self.read_idx == self.write_idx && self.buffer[self.read_idx as usize].is_none() {
    92→            return None;
    93→        }
    94→
    95→        let read_pos = self.read_idx as usize;
    96→        let event = self.buffer[read_pos].as_ref().map(|e| e.clone());
    97→
    98→        if event.is_some() {
    99→            self.buffer[read_pos] = None;
   100→            self.read_idx = (self.read_idx + 1) % self.capacity;
   101→        }
   102→
   103→        event
   104→    }
   105→
   106→    /// 버퍼 크기
   107→    pub fn len(&self) -> u32 {
   108→        let read_pos = self.read_idx;
   109→        let write_pos = self.write_idx;
   110→
   111→        if write_pos >= read_pos {
   112→            write_pos - read_pos
   113→        } else {
   114→            (self.capacity - read_pos) + write_pos
   115→        }
   116→    }
   117→
   118→    /// 버퍼 비어있는지 확인
   119→    pub fn is_empty(&self) -> bool {
   120→        self.len() == 0
   121→    }
   122→
   123→    /// 버퍼 가득 찼는지 확인
   124→    pub fn is_full(&self) -> bool {
   125→        self.len() >= self.capacity - 1
   126→    }
   127→
   128→    pub fn clone(&self) -> Self {
   129→        let mut new_buffer = [None; 4096];
   130→        for i in 0..4096 {
   131→            if let Some(event) = &self.buffer[i] {
   132→                new_buffer[i] = Some(event.clone());
   133→            }
   134→        }
   135→
   136→        ZeroCopyRingBuffer {
   137→            buffer: new_buffer,
   138→            write_idx: self.write_idx,
   139→            read_idx: self.read_idx,
   140→            capacity: self.capacity,
   141→            total_events: self.total_events,
   142→        }
   143→    }
   144→}
   145→
   146→// ============================================================================
   147→// 3. 커밋 버스
   148→// ============================================================================
   149→
   150→pub struct CommitBus {
   151→    pub ring: ZeroCopyRingBuffer,
   152→    pub commit_batch_size: u32,       // 배치 크기 (64)
   153→    pub committed_epochs: u64,        // 커밋된 에포크
   154→    pub committed_tx_count: u64,
   155→    pub pending_tx_count: u32,
   156→}
   157→
   158→impl CommitBus {
   159→    pub fn new() -> Self {
   160→        CommitBus {
   161→            ring: ZeroCopyRingBuffer::new(),
   162→            commit_batch_size: 64,
   163→            committed_epochs: 0,
   164→            committed_tx_count: 0,
   165→            pending_tx_count: 0,
   166→        }
   167→    }
   168→
   169→    /// 트랜잭션 투입 (O(1))
   170→    pub fn submit_tx(&mut self, event: TxEvent) -> bool {
   171→        if self.ring.push(event) {
   172→            self.pending_tx_count += 1;
   173→            return true;
   174→        }
   175→        false
   176→    }
   177→
   178→    /// 배치 커밋 (64개 트랜잭션)
   179→    pub fn commit_batch(&mut self) -> Vec<TxEvent> {
   180→        let mut batch = Vec::new();
   181→
   182→        for _ in 0..self.commit_batch_size {
   183→            if let Some(event) = self.ring.pop() {
   184→                batch.push(event);
   185→                self.committed_tx_count += 1;
   186→                if self.pending_tx_count > 0 {
   187→                    self.pending_tx_count -= 1;
   188→                }
   189→            } else {
   190→                break;
   191→            }
   192→        }
   193→
   194→        if batch.len() > 0 {
   195→            self.committed_epochs += 1;
   196→        }
   197→
   198→        batch
   199→    }
   200→
   201→    /// 배치 크기 설정 (기본 64)
   202→    pub fn set_batch_size(&mut self, size: u32) {
   203→        self.commit_batch_size = size.min(4096);
   204→    }
   205→
   206→    /// 대기 중인 트랜잭션 개수
   207→    pub fn pending_count(&self) -> u32 {
   208→        self.pending_tx_count
   209→    }
   210→
   211→    /// 처리량 (tx/s)
   212→    pub fn throughput_tps(&self) -> f32 {
   213→        if self.committed_epochs == 0 {
   214→            return 0.0;
   215→        }
   216→
   217→        // 시뮬레이션: 각 에포크 = 1ms
   218→        let seconds = (self.committed_epochs as f32) / 1000.0;
   219→        self.committed_tx_count as f32 / seconds
   220→    }
   221→
   222→    /// 배치 커밋 성공률
   223→    pub fn batch_success_rate(&self) -> f32 {
   224→        if self.committed_epochs == 0 {
   225→            return 0.0;
   226→        }
   227→
   228→        // 완전 배치 수 (64개 모두 커밋된)
   229→        let full_batches = self.committed_tx_count / (self.commit_batch_size as u64);
   230→        (full_batches as f32 / self.committed_epochs as f32) * 100.0
   231→    }
   232→
   233→    pub fn clone(&self) -> Self {
   234→        CommitBus {
   235→            ring: self.ring.clone(),
   236→            commit_batch_size: self.commit_batch_size,
   237→            committed_epochs: self.committed_epochs,
   238→            committed_tx_count: self.committed_tx_count,
   239→            pending_tx_count: self.pending_tx_count,
   240→        }
   241→    }
   242→}
   243→
   244→// ============================================================================
   245→// 4. 버스 통계
   246→// ============================================================================
   247→
   248→pub struct BusStats {
   249→    pub total_tx_submitted: u64,
   250→    pub total_tx_committed: u64,
   251→    pub total_batches: u64,
   252→    pub dropped_tx: u64,
   253→}
   254→
   255→impl BusStats {
   256→    pub fn new() -> Self {
   257→        BusStats {
   258→            total_tx_submitted: 0,
   259→            total_tx_committed: 0,
   260→            total_batches: 0,
   261→            dropped_tx: 0,
   262→        }
   263→    }
   264→
   265→    pub fn commit_rate(&self) -> f32 {
   266→        if self.total_tx_submitted == 0 {
   267→            return 0.0;
   268→        }
   269→
   270→        (self.total_tx_committed as f32 / self.total_tx_submitted as f32) * 100.0
   271→    }
   272→
   273→    pub fn loss_rate(&self) -> f32 {
   274→        if self.total_tx_submitted == 0 {
   275→            return 0.0;
   276→        }
   277→
   278→        (self.dropped_tx as f32 / self.total_tx_submitted as f32) * 100.0
   279→    }
   280→
   281→    pub fn clone(&self) -> Self {
   282→        BusStats {
   283→            total_tx_submitted: self.total_tx_submitted,
   284→            total_tx_committed: self.total_tx_committed,
   285→            total_batches: self.total_batches,
