   253→// ----- KV Operations -----
   254→
   255→fn put(store: ShardedKVStore, key: string, value: string) -> ShardedKVStore {
   256→    let primary = get_node_for_key(store.ring, key);
   257→    let replicas = get_replica_nodes(store.ring, key, store.replication_factor);
   258→
   259→    // Store in data map
