    70→// ----- Write Operation -----
    71→
    72→fn db_write(db: RaftShardedDB, key: string, value: string) -> RaftShardedDB {
    73→    db.metrics.total_writes = db.metrics.total_writes + 1;
    74→
    75→    // Step 1: Determine primary node via consistent hashing
    76→    let primary_node = get_node_for_key(db.ring, key);
    77→
    78→    // Step 2: Check if primary is alive
    79→    if (db.raft_nodes[primary_node].state == RaftState.Leader) {
    80→        // Step 3: Replicate to other nodes
    81→        let replicas = get_replica_nodes(db.ring, key, db.replication_factor);
    82→
    83→        // Step 4: Majority commit check
    84→        let replicated = 0;
    85→        let i = 0;
    86→        while (i < replicas.len()) {
    87→            replicated = replicated + 1;
    88→            i = i + 1;
    89→        };
    90→
    91→        let quorum_size = (replicas.len() / 2) + 1;
    92→        if (replicated >= quorum_size) {
    93→            // Step 5: Commit and store
    94→            db.data_store[key] = value;
    95→            db.metrics.successful_writes = db.metrics.successful_writes + 1;
    96→
    97→            print("DB Write OK: key=" + key + " value=" + value + " replicas=" + replicas.len());
    98→        } else {
    99→            print("DB Write FAIL: Not enough replicas (got " + replicated + ", need " + quorum_size + ")");
   100→        };
   101→    } else {
   102→        print("DB Write FAIL: Primary node not leader");
   103→    };
   104→
   105→    db
   106→}
   107→
   108→// ----- Read Operation -----
   109→
   110→fn db_read(db: RaftShardedDB, key: string) -> string {
   111→    db.metrics.total_reads = db.metrics.total_reads + 1;
   112→
   113→    // Try primary first
   114→    let primary_node = get_node_for_key(db.ring, key);
   115→
   116→    if (db.raft_nodes[primary_node].state == RaftState.Leader ||
   117→        db.raft_nodes[primary_node].state == RaftState.Follower) {
   118→        let value = db.data_store[key];
   119→        if (value.len() > 0) {
   120→            db.metrics.successful_reads = db.metrics.successful_reads + 1;
   121→            print("DB Read OK: key=" + key + " value=" + value);
   122→            return value;
   123→        };
   124→    };
   125→
   126→    // Try replicas
   127→    let replicas = get_replica_nodes(db.ring, key, db.replication_factor);
   128→    let i = 0;
   129→    while (i < replicas.len()) {
   130→        let replica_id = replicas[i];
   131→        if (db.raft_nodes[replica_id].state != RaftState.Leader) {
   132→            // Try stale read from replica
   133→            let value = db.data_store[key];
   134→            if (value.len() > 0) {
   135→                db.metrics.successful_reads = db.metrics.successful_reads + 1;
   136→                print("DB Read OK (from replica): key=" + key);
   137→                return value;
   138→            };
   139→        };
   140→        i = i + 1;
   141→    };
   142→
   143→    print("DB Read FAIL: Key not found");
   144→    ""
   145→}
