/* ============================================================================
   Registry Layer Tests (B1-C6) - Unforgiving Tests

   목적: Challenge 16 Identity-Proof (ZKP 도메인 소유권) 검증
   특징:
   - B1-B6: DNS 레코드 등록 (ZKP, TTL, CAS, 중복 방지)
   - C1-C6: RecordType + 업데이트 (버전 체인, 무결성)

   총 12개 무관용 테스트
============================================================================ */

#[cfg(test)]
mod registry_tests {
    // ================================================================
    // B1: 도메인 등록 (ZKP 소유권)
    // ================================================================

    #[test]
    fn test_b1_domain_registration_with_zkp() {
        // DnsRecord + ZKP 증명으로 도메인 등록
        let mut registry = SovereignRegistry::new();

        let mut domain = [0u8; 253];
        domain[0] = b'k';
        domain[1] = b'i';
        domain[2] = b'm';  // "kim"

        let mut record = DnsRecord::new(domain, RecordType::A, [0u8; 512], 3600);
        let mut value = [0u8; 512];
        value[0] = 127;  // 127.0.0.1
        value[1] = 0;
        value[2] = 0;
        value[3] = 1;
        record.value = value;
        record.value_len = 4;

        let proof = DnsProof {
            commitment: [1u8; 32],
            challenge: [2u8; 32],
            response: [3u8; 32],
            domain_hash: [0u8; 32],
            nonce: 12345,
        };

        let owner = [0xAAu8; 32];

        let result = registry.register_domain(record, &proof, owner);
        assert!(result, "도메인 등록 실패");
        assert_eq!(registry.record_count, 1);

        println!("✅ B1: 도메인 등록 (ZKP) 통과");
    }

    // ================================================================
    // B2: TTL 만료 검증
    // ================================================================

    #[test]
    fn test_b2_ttl_expiration() {
        let mut registry = SovereignRegistry::new();

        let mut domain = [0u8; 253];
        domain[0] = b't';
        domain[1] = b't';
        domain[2] = b'l';

        let record = DnsRecord::new(domain, RecordType::A, [0u8; 512], 100);  // TTL = 100초

        let proof = DnsProof {
            commitment: [1u8; 32],
            challenge: [2u8; 32],
            response: [3u8; 32],
            domain_hash: [0u8; 32],
            nonce: 12345,
        };

        let owner = [0xAAu8; 32];

        registry.register_domain(record, &proof, owner);

        // 기록된 레코드 확인
        let found = registry.lookup_record(&domain);
        assert!(found.is_some(), "레코드 조회 실패");
        assert!(!found.unwrap().is_expired(), "아직 TTL이 유효해야 함");

        println!("✅ B2: TTL 만료 검증 통과");
    }

    // ================================================================
    // B3: CAS 저장
    // ================================================================

    #[test]
    fn test_b3_cas_storage() {
        let mut registry = SovereignRegistry::new();

        let mut domain = [0u8; 253];
        domain[0] = b'c';
        domain[1] = b'a';
        domain[2] = b's';

        let record = DnsRecord::new(domain, RecordType::A, [0u8; 512], 3600);

        let proof = DnsProof {
            commitment: [1u8; 32],
            challenge: [2u8; 32],
            response: [3u8; 32],
            domain_hash: [0u8; 32],
            nonce: 12345,
        };

        let owner = [0xBBu8; 32];

        registry.register_domain(record, &proof, owner);

        // CAS 저장 확인
        assert!(registry.cas.chunk_count > 0, "CAS에 저장되지 않음");
        assert_eq!(registry.total_stored, 1);

        // 청크 존재 확인
        let has_chunk = registry.cas.has_chunk(0);
        assert!(has_chunk, "CAS 청크 0이 없음");

        println!("✅ B3: CAS 저장 통과 ({} chunks)", registry.cas.chunk_count);
    }

    // ================================================================
    // B4: 소유자 확인
    // ================================================================

    #[test]
    fn test_b4_owner_verification() {
        let mut registry = SovereignRegistry::new();

        let mut domain = [0u8; 253];
        domain[0] = b'o';
        domain[1] = b'w';
        domain[2] = b'n';

        let record = DnsRecord::new(domain, RecordType::MX, [0u8; 512], 3600);
        let proof = DnsProof {
            commitment: [1u8; 32],
            challenge: [2u8; 32],
            response: [3u8; 32],
            domain_hash: [0u8; 32],
            nonce: 12345,
        };

        let owner = [0xCCu8; 32];

        registry.register_domain(record, &proof, owner);

        // 소유자 조회
        let found_owner = registry.lookup_owner(&domain);
        assert!(found_owner.is_some(), "소유자 조회 실패");

        let found_owner_hash = found_owner.unwrap();
        for i in 0..32 {
            assert_eq!(found_owner_hash[i], owner[i], "소유자 불일치 at index {}", i);
        }

        println!("✅ B4: 소유자 확인 통과");
    }

    // ================================================================
    // B5: 중복 등록 거부
    // ================================================================

    #[test]
    fn test_b5_duplicate_registration_rejected() {
        let mut registry = SovereignRegistry::new();

        let mut domain = [0u8; 253];
        domain[0] = b'd';
        domain[1] = b'u';
