   344→    pub query_type: u8,
   345→    pub client_ip: u32,
   346→    pub is_recursive: bool,
   347→}
   348→
   349→impl DnsPathOptimizer {
   350→    fn new() -> Self {
   351→        let mut optimizer = DnsPathOptimizer {
   352→            nn_weights: [[0.1f32; 8]; 16],
   353→            nn_bias: [0.0f32; 8],
   354→            total_decisions: 0,
   355→            fast_decisions: 0,
   356→            slow_decisions: 0,
   357→            pattern_window: [0; 32],
   358→            window_idx: 0,
   359→            anomaly_count: 0,
   360→        };
   361→
   362→        for i in 0..16 {
   363→            for j in 0..8 {
   364→                let weight = ((i * 7 + j * 13) as f32 + 1.0) / 256.0;
   365→                optimizer.nn_weights[i][j] = weight.max(0.01).min(0.99);
   366→            }
   367→        }
   368→
   369→        for j in 0..8 {
   370→            optimizer.nn_bias[j] = ((j as f32) - 4.0) * 0.1;
   371→        }
   372→
   373→        optimizer
   374→    }
   375→
   376→    fn optimize_path(&mut self, query: &DnsQuery) -> ResolverPath {
   377→        let start = get_optimizer_time();
   378→
   379→        let mut hidden: [f32; 8] = [0.0f32; 8];
   380→        for j in 0..8 {
   381→            let mut sum = self.nn_bias[j];
   382→            for i in 0..16 {
   383→                sum += 0.1 * self.nn_weights[i][j];
   384→            }
   385→            hidden[j] = if sum > 0.0 { sum } else { 0.0 };
   386→        }
   387→
   388→        let mut path_score = [0.0f32; 8];
   389→        let mut sum_exp = 0.0f32;
   390→
   391→        for j in 0..8 {
   392→            let exp_val = (hidden[j] * 2.0).exp().min(100.0);
   393→            path_score[j] = exp_val;
   394→            sum_exp += exp_val;
   395→        }
   396→
   397→        if sum_exp > 0.0 {
   398→            for j in 0..8 {
   399→                path_score[j] /= sum_exp;
   400→            }
   401→        }
   402→
   403→        let mut selected_path = 0u8;
   404→        let mut max_score = path_score[0];
   405→
   406→        for j in 1..8 {
   407→            if path_score[j] > max_score {
   408→                max_score = path_score[j];
   409→                selected_path = j as u8;
   410→            }
   411→        }
   412→
   413→        let path_type = match selected_path {
   414→            0 => ResolverPathType::LocalCache,
   415→            1 => ResolverPathType::DhtFast,
   416→            2 => ResolverPathType::DhtBalanced,
   417→            3 => ResolverPathType::DhtThorough,
   418→            4 => ResolverPathType::CacheThenDht,
   419→            5 => ResolverPathType::ParallelPath,
   420→            6 => ResolverPathType::ProactiveRefresh,
   421→            _ => ResolverPathType::FallbackSecondary,
   422→        };
   423→
   424→        let elapsed = get_optimizer_time() - start;
   425→
   426→        self.total_decisions += 1;
   427→        if elapsed < 5_000_000 {
   428→            self.fast_decisions += 1;
   429→        } else {
   430→            self.slow_decisions += 1;
   431→        }
   432→
   433→        self.pattern_window[self.window_idx as usize] = selected_path;
   434→        self.window_idx = (self.window_idx + 1) % 32;
   435→
   436→        ResolverPath {
   437→            path_type,
   438→            selected_path,
   439→            confidence: max_score,
   440→        }
   441→    }
   442→
   443→    fn analyze_query_pattern(&mut self, domain: &[u8]) -> QueryAnomaly {
   444→        let mut bigram_counts = [0u32; 256];
   445→        let mut total_bigrams = 0u32;
   446→
   447→        for i in 0..domain.len().saturating_sub(1) {
   448→            if domain[i] == 0 {
   449→                break;
   450→            }
   451→
   452→            let bigram_val = (domain[i] as usize ^ (domain[i + 1] as usize << 4)) % 256;
   453→            bigram_counts[bigram_val] += 1;
   454→            total_bigrams += 1;
   455→        }
   456→
   457→        let mut entropy = 0.0f32;
   458→        for count in &bigram_counts {
   459→            if *count > 0 {
   460→                let prob = (*count as f32) / (total_bigrams as f32 + 1.0);
   461→                entropy -= prob * prob.log2();
   462→            }
   463→        }
   464→
   465→        let is_anomaly = entropy > 4.0;
   466→        let anomaly_score = (entropy - 3.0).max(0.0) / 5.0;
   467→
   468→        if is_anomaly {
   469→            self.anomaly_count += 1;
   470→        }
   471→
   472→        QueryAnomaly {
   473→            is_anomaly,
   474→            anomaly_score: anomaly_score.min(1.0),
   475→        }
   476→    }
   477→
   478→    fn stats(&self) -> (u64, u64, u64, u64) {
   479→        (self.total_decisions, self.fast_decisions, self.slow_decisions, self.anomaly_count)
   480→    }
   481→}
