            domain[0] = b'h';
            domain[1] = b'3';
            domain[2] = ((i / 10) as u8 + b'0');
            domain[3] = ((i % 10) as u8 + b'0');

            let query = DnsQuery {
                domain,
                query_type: (i % 7) as u8,
                client_ip: 0x7F000001 + (i as u32),
                is_recursive: i % 2 == 0,
            };

            let path = optimizer.optimize_path(&query);
            paths_used[path.selected_path as usize] = true;

            let _found = resolver.resolve(&domain);
        }

        let distinct_paths = paths_used.iter().filter(|&&used| used).count();
        assert!(distinct_paths >= 2, "경로 다양성 부족");

