        }

        let (_total, _fast, _slow, anomalies) = optimizer.stats();
        assert!(anomalies >= 0, "이상 카운터 기록");

        println!("✅ E6: 이상 쿼리 통계 통과 (detected: {})", anomalies);
    }

    // ================================================================
    // F1: 배치 도메인 해석 (처리량)
    // ================================================================

    #[test]
    fn test_f1_batch_domain_resolution() {
        let mut resolver = SovereignResolver::new(NodeId::new([6; 20]));

        // 100개 도메인 해석
        for i in 0..100 {
            let mut domain = [0u8; 253];
            domain[0] = b'f';
            domain[1] = b'1';
            domain[2] = ((i / 10) as u8 + b'0');
            domain[3] = ((i % 10) as u8 + b'0');

            let _found = resolver.resolve(&domain);
        }

