    #[test]
    fn test_g1_cache_reconstruction() {
        let mut resolver = SovereignResolver::new(NodeId::new([10; 20]));

        // 초기 캐시 상태: 50개 레코드
        for i in 0..50 {
            let mut domain = [0u8; 253];
            domain[0] = b'g';
            domain[1] = b'1';
