            let record = DnsRecord::new(domain, RecordType::A, [0u8; 512], 3600);
            let cache_idx = resolver.hash_domain(&domain) as usize % 4096;
            resolver.cache[cache_idx] = Some((record, get_resolver_time() + 3600_000_000_000u64));
            resolver.cache_count += 1;
        }

        // 일부 캐시 항목 삭제 (50%)
        let initial_count = resolver.cache_count;
        for i in 0..(initial_count / 2) {
            let mut domain = [0u8; 253];
            domain[0] = b'g';
            domain[1] = b'1';
            domain[2] = ((i as u32 / 10) as u8 + b'0');
            domain[3] = ((i as u32 % 10) as u8 + b'0');

            let cache_idx = resolver.hash_domain(&domain) as usize % 4096;
            resolver.cache[cache_idx] = None;
            resolver.cache_count = resolver.cache_count.saturating_sub(1);
        }

        // 캐시가 반으로 줄어듦 확인
        assert_eq!(resolver.cache_count, initial_count / 2);

        println!("✅ G1: 캐시 재구성 통과 ({}→{} 레코드)", initial_count, resolver.cache_count);
    }

