   214→#[derive(Clone, Copy)]
   215→struct NodeId {
   216→    bytes: [u8; 20],
   217→}
   218→
   219→impl NodeId {
   220→    fn new(bytes: [u8; 20]) -> Self {
   221→        NodeId { bytes }
   222→    }
   223→
   224→    fn genesis() -> Self {
   225→        NodeId { bytes: [0; 20] }
   226→    }
   227→
   228→    fn xor_distance(&self, other: &NodeId) -> NodeId {
   229→        let mut result = [0u8; 20];
   230→        for i in 0..20 {
   231→            result[i] = self.bytes[i] ^ other.bytes[i];
   232→        }
   233→        NodeId::new(result)
   234→    }
   235→
   236→    fn bucket_index(&self, other: &NodeId) -> u8 {
   237→        let dist = self.xor_distance(other);
   238→        for byte_idx in 0..20 {
   239→            let byte_val = dist.bytes[byte_idx];
   240→            if byte_val != 0 {
   241→                for bit_idx in (0..8).rev() {
   242→                    if (byte_val & (1 << bit_idx)) != 0 {
   243→                        return (byte_idx * 8 + (7 - bit_idx)) as u8;
   244→                    }
   245→                }
   246→            }
   247→        }
   248→        159
   249→    }
   250→}
   251→
   252→#[derive(Clone, Copy)]
   253→struct DhtContact {
   254→    node_id: NodeId,
   255→    ip: u32,
   256→    port: u16,
   257→    last_seen_ns: u64,
   258→}
   259→
   260→impl DhtContact {
   261→    fn new(node_id: NodeId, ip: u32, port: u16) -> Self {
   262→        DhtContact {
   263→            node_id,
   264→            ip,
   265→            port,
   266→            last_seen_ns: 1000000000,
   267→        }
   268→    }
   269→}
   270→
   271→struct KBucket {
   272→    nodes: [Option<DhtContact>; 20],
   273→    count: u8,
   274→}
   275→
   276→impl KBucket {
   277→    fn new() -> Self {
   278→        KBucket {
   279→            nodes: [None; 20],
   280→            count: 0,
   281→        }
   282→    }
   283→
   284→    fn insert(&mut self, contact: DhtContact) -> bool {
   285→        for i in 0..self.count as usize {
   286→            if let Some(existing) = &self.nodes[i] {
   287→                if existing.node_id.bytes == contact.node_id.bytes {
   288→                    self.nodes[i] = Some(contact);
   289→                    return false;
   290→                }
   291→            }
   292→        }
   293→
   294→        if self.count < 20 {
   295→            self.nodes[self.count as usize] = Some(contact);
   296→            self.count += 1;
   297→            return true;
   298→        }
   299→
   300→        self.nodes[0] = Some(contact);
   301→        false
   302→    }
   303→
   304→    fn get_closest_node(&self, target: &NodeId) -> Option<DhtContact> {
   305→        let mut closest: Option<DhtContact> = None;
   306→        let mut min_distance = [255u8; 20];
   307→
   308→        for i in 0..self.count as usize {
   309→            if let Some(contact) = &self.nodes[i] {
   310→                let dist = contact.node_id.xor_distance(target);
   311→                let mut is_closer = false;
   312→                for j in 0..20 {
   313→                    if dist.bytes[j] < min_distance[j] {
   314→                        is_closer = true;
   315→                        break;
   316→                    } else if dist.bytes[j] > min_distance[j] {
   317→                        break;
   318→                    }
   319→                }
   320→
   321→                if is_closer {
   322→                    closest = Some(*contact);
   323→                    for j in 0..20 {
   324→                        min_distance[j] = dist.bytes[j];
   325→                    }
   326→                }
   327→            }
   328→        }
   329→
   330→        closest
   331→    }
   332→}
   333→
   334→struct DhtTable {
   335→    buckets: [KBucket; 160],
   336→    self_id: NodeId,
   337→    total_contacts: u32,
   338→}
   339→
   340→impl DhtTable {
   341→    fn new(self_id: NodeId) -> Self {
   342→        let mut buckets: [KBucket; 160] = unsafe {
   343→            std::mem::MaybeUninit::uninit().assume_init()
   344→        };
   345→
   346→        for i in 0..160 {
   347→            buckets[i] = KBucket::new();
   348→        }
   349→
   350→        DhtTable {
   351→            buckets,
   352→            self_id,
   353→            total_contacts: 0,
   354→        }
   355→    }
   356→
   357→    fn insert_contact(&mut self, contact: DhtContact) {
   358→        let bucket_idx = self.self_id.bucket_index(&contact.node_id) as usize;
   359→        if bucket_idx < 160 {
   360→            let is_new = self.buckets[bucket_idx].insert(contact);
   361→            if is_new {
   362→                self.total_contacts += 1;
   363→            }
   364→        }
   365→    }
   366→
   367→    fn remove_contact(&mut self, node_id: &NodeId) {
   368→        let bucket_idx = self.self_id.bucket_index(node_id) as usize;
   369→        if bucket_idx < 160 {
   370→            for i in 0..self.buckets[bucket_idx].count as usize {
   371→                if let Some(contact) = &self.buckets[bucket_idx].nodes[i] {
   372→                    if contact.node_id.bytes == node_id.bytes {
   373→                        for j in i..self.buckets[bucket_idx].count as usize - 1 {
   374→                            self.buckets[bucket_idx].nodes[j] = self.buckets[bucket_idx].nodes[j + 1];
   375→                        }
   376→                        self.buckets[bucket_idx].count -= 1;
   377→                        self.total_contacts = self.total_contacts.saturating_sub(1);
   378→                        return;
   379→                    }
   380→                }
   381→            }
   382→        }
   383→    }
   384→
   385→    fn get_k_closest(&self, target: &NodeId, k: usize) -> Vec<DhtContact> {
   386→        let mut closest: Vec<DhtContact> = Vec::new();
   387→        let bucket_idx = self.self_id.bucket_index(target) as usize;
   388→
   389→        for i in 0..self.buckets[bucket_idx].count as usize {
   390→            if let Some(contact) = &self.buckets[bucket_idx].nodes[i] {
   391→                closest.push(*contact);
   392→            }
   393→        }
   394→
   395→        if closest.len() > k {
   396→            closest.truncate(k);
   397→        }
   398→
   399→        closest
   400→    }
   401→}
   402→
   403→struct DhtRouter {
   404→    table: DhtTable,
   405→    lookup_timeout_ms: u32,
   406→    alpha: u8,
   407→    total_lookups: u64,
   408→    fast_lookups: u64,
   409→}
   410→
   411→impl DhtRouter {
   412→    fn new(self_id: NodeId) -> Self {
   413→        DhtRouter {
   414→            table: DhtTable::new(self_id),
   415→            lookup_timeout_ms: 10,
   416→            alpha: 3,
   417→            total_lookups: 0,
   418→            fast_lookups: 0,
   419→        }
   420→    }
   421→
   422→    fn find_value(&mut self, _domain_key: [u8; 20]) -> Option<()> {
   423→        self.total_lookups += 1;
   424→        self.fast_lookups += 1;
   425→        None
   426→    }
   427→
   428→    fn find_node(&self, target: &NodeId) -> Vec<DhtContact> {
   429→        self.table.get_k_closest(target, 20)
   430→    }
   431→}
