   201→// 4. Signal Detector (앙상블)
   202→// ============================================================================
   203→
   204→pub struct SignalDetector {
   205→    pub nn: L0NeuralNet,                    // Phase 8 L0NeuralNet
   206→    pub ngram: NgramAnalyzer,               // behavioral_analyzer.fl N-gram
   207→    pub ensemble_weights: [f32; 3],         // [0.6, 0.3, 0.1] = NN, 규칙, 이상치
   208→    pub threat_threshold: f32,              // 0.5 (50% 신뢰도)
