/* ============================================================================
   Raft Consensus Algorithm - Complete Implementation

   목표: 3노드 이상에서 완전한 리더 선출 및 로그 복제
   성능: < 300ms 리더 선출, 과반수 커밋

   크기: 600줄
============================================================================ */

// ============================================================================
// 1. 핵심 구조체
// ============================================================================

pub enum RaftState {
    Follower,
    Candidate,
    Leader,
}

impl RaftState {
    pub fn to_string(&self) -> String {
        match self {
            RaftState::Follower => "Follower".to_string(),
            RaftState::Candidate => "Candidate".to_string(),
            RaftState::Leader => "Leader".to_string(),
        }
    }
}

pub struct LogEntry {
    pub term: u64,
    pub index: u64,
    pub command: String,
    pub committed: bool,
}

impl LogEntry {
    pub fn new(term: u64, index: u64, command: String) -> Self {
        LogEntry {
            term,
            index,
            command,
            committed: false,
        }
    }
}

pub struct VoteRequest {
    pub term: u64,
    pub candidate_id: u32,
    pub last_log_index: u64,
    pub last_log_term: u64,
}

pub struct VoteResponse {
    pub term: u64,
    pub vote_granted: bool,
}

pub struct AppendEntriesRequest {
    pub term: u64,
    pub leader_id: u32,
    pub prev_log_index: u64,
    pub prev_log_term: u64,
    pub entries: Vec<LogEntry>,
    pub leader_commit: u64,
}

pub struct AppendEntriesResponse {
    pub term: u64,
    pub success: bool,
}

// ============================================================================
// 2. Raft 노드 핵심
// ============================================================================

pub struct RaftNode {
    pub id: u32,
    pub state: RaftState,
    pub current_term: u64,
    pub voted_for: Option<u32>,
    pub log: Vec<LogEntry>,
    pub commit_index: u64,
    pub last_applied: u64,
    pub election_timeout_ms: u32,
    pub votes_received: u32,
    pub next_index: Vec<u64>,
    pub match_index: Vec<u64>,
    pub cluster_size: u32,
    pub election_count: u64,
    pub commit_count: u64,
}

impl RaftNode {
    pub fn new(id: u32, cluster_size: u32) -> Self {
        let next_index = vec![1u64; cluster_size as usize];
        let match_index = vec![0u64; cluster_size as usize];

        RaftNode {
            id,
            state: RaftState::Follower,
            current_term: 0,
            voted_for: None,
            log: Vec::new(),
            commit_index: 0,
            last_applied: 0,
            election_timeout_ms: 150 + (id as u32 * 50) % 150,
            votes_received: 0,
            next_index,
            match_index,
            cluster_size,
            election_count: 0,
            commit_count: 0,
        }
    }

    // ========================================================================
    // 3. 선출 처리
    // ========================================================================

    pub fn start_election(&mut self) -> VoteRequest {
        self.state = RaftState::Candidate;
        self.current_term += 1;
        self.voted_for = Some(self.id);
        self.votes_received = 1;
        self.election_count += 1;

        let last_log_index = if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].index
        };

        let last_log_term = if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].term
        };

        VoteRequest {
            term: self.current_term,
            candidate_id: self.id,
            last_log_index,
            last_log_term,
        }
    }

    pub fn handle_vote_request(&mut self, req: &VoteRequest) -> VoteResponse {
        // Safety 조건 1: Term 비교
        if req.term < self.current_term {
            return VoteResponse {
                term: self.current_term,
                vote_granted: false,
            };
        }

        // Term이 더 크면 업데이트
        if req.term > self.current_term {
            self.current_term = req.term;
            self.voted_for = None;
            self.state = RaftState::Follower;
        }

        // Safety 조건 2: 이미 투표했는가?
        if let Some(voted_for) = self.voted_for {
            if voted_for != req.candidate_id {
                return VoteResponse {
                    term: self.current_term,
                    vote_granted: false,
                };
            }
        }

        // Safety 조건 3: Log Matching (Candidate의 로그가 더 최신인가?)
        let last_log_index = if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].index
        };

        let last_log_term = if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].term
        };

        if req.last_log_term < last_log_term {
            return VoteResponse {
                term: self.current_term,
                vote_granted: false,
            };
        }

        if req.last_log_term == last_log_term && req.last_log_index < last_log_index {
            return VoteResponse {
                term: self.current_term,
                vote_granted: false,
            };
        }

        // 투표 부여
        self.voted_for = Some(req.candidate_id);
        VoteResponse {
            term: self.current_term,
            vote_granted: true,
        }
    }

    pub fn become_leader(&mut self) {
        self.state = RaftState::Leader;

        // Leader 전용 인덱스 초기화
        let last_log_index = if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].index
        };

        for i in 0..self.cluster_size as usize {
            if i != self.id as usize {
                self.next_index[i] = last_log_index + 1;
                self.match_index[i] = 0;
            }
        }
    }

    // ========================================================================
    // 4. 로그 복제
    // ========================================================================

    pub fn replicate_log(&mut self, command: String) -> LogEntry {
        let index = if self.log.is_empty() {
            1
        } else {
            self.log[self.log.len() - 1].index + 1
        };

        let entry = LogEntry::new(self.current_term, index, command);
        self.log.push(entry.clone());

        entry
    }

    pub fn handle_append_entries(&mut self, req: &AppendEntriesRequest) -> AppendEntriesResponse {
        // Term 비교
        if req.term < self.current_term {
            return AppendEntriesResponse {
                term: self.current_term,
                success: false,
            };
        }

        // Term이 더 크면 업데이트
        if req.term > self.current_term {
            self.current_term = req.term;
            self.voted_for = None;
        }

        // Follower로 전환
        self.state = RaftState::Follower;

        // Safety 조건: Log Matching
        if req.prev_log_index > 0 {
            let mut found = false;
            for entry in &self.log {
                if entry.index == req.prev_log_index && entry.term == req.prev_log_term {
                    found = true;
                    break;
                }
            }

            if !found {
                return AppendEntriesResponse {
                    term: self.current_term,
                    success: false,
                };
            }
        }

        // 로그 복제
        for entry in &req.entries {
            self.log.push(entry.clone());
        }

        // Commit 업데이트
        if req.leader_commit > self.commit_index {
            self.commit_index = req.leader_commit.min(self.get_last_log_index());
        }

        AppendEntriesResponse {
            term: self.current_term,
            success: true,
        }
    }

    pub fn commit_entries(&mut self) {
        // 과반수(N/2 + 1)가 복제한 엔트리 확인
        let majority = (self.cluster_size / 2) + 1;

        for index in (self.commit_index + 1)..=self.get_last_log_index() {
            let mut match_count = 1; // Leader 자신

            for match_idx in &self.match_index {
                if *match_idx >= index {
                    match_count += 1;
                }
            }

            if match_count >= majority {
                self.commit_index = index;
                self.commit_count += 1;
            }
        }
    }

    pub fn apply_committed(&mut self) {
        while self.last_applied < self.commit_index {
            self.last_applied += 1;
            // State Machine에 적용 (시뮬레이션)
        }
    }

    // ========================================================================
    // 5. 유틸리티
    // ========================================================================

    pub fn get_last_log_index(&self) -> u64 {
        if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].index
        }
    }

    pub fn get_last_log_term(&self) -> u64 {
        if self.log.is_empty() {
            0
        } else {
            self.log[self.log.len() - 1].term
        }
    }

    pub fn get_state_string(&self) -> String {
        format!(
            "Node {} (Term: {}, State: {}, LogSize: {})",
            self.id,
            self.current_term,
            match self.state {
                RaftState::Follower => "Follower",
                RaftState::Candidate => "Candidate",
                RaftState::Leader => "Leader",
            },
            self.log.len()
        )
    }

    pub fn is_leader(&self) -> bool {
        matches!(self.state, RaftState::Leader)
    }

    pub fn is_candidate(&self) -> bool {
        matches!(self.state, RaftState::Candidate)
    }

    pub fn is_follower(&self) -> bool {
        matches!(self.state, RaftState::Follower)
    }
}

impl Clone for LogEntry {
    fn clone(&self) -> Self {
        LogEntry {
            term: self.term,
            index: self.index,
            command: self.command.clone(),
            committed: self.committed,
        }
    }
}

impl Clone for RaftState {
    fn clone(&self) -> Self {
        match self {
            RaftState::Follower => RaftState::Follower,
            RaftState::Candidate => RaftState::Candidate,
            RaftState::Leader => RaftState::Leader,
        }
    }
}

impl Clone for RaftNode {
    fn clone(&self) -> Self {
        RaftNode {
            id: self.id,
            state: self.state.clone(),
            current_term: self.current_term,
            voted_for: self.voted_for,
            log: self.log.clone(),
